"""Independently written P1 integration notes, examples and complete-answer checks."""
import sympy as s
x,y,t=s.symbols('x y t',real=True);u=s.Symbol('u',positive=True)
lessons,questions,models=[],[],[]

def tex(v):return s.latex(s.sympify(str(v),locals={'x':x,'y':y,'t':t,'u':u}))
def math(v):return r'\('+tex(v)+r'\)'
def image(name,alt):return '<p><img src="/assets/original/integration/'+name+'.svg" alt="'+alt+'"></p>'
def ex(title,question,solution,key):return dict(title=title,question=question,solution=solution,verification=key)
def lesson(key,suffix,title,summary,objective,before,ideas,method,mistakes,examples):
 lessons.append(dict(key=key,id='orig_integration_'+suffix,title=title,summary=summary,objective=objective,before=before,ideas=ideas,method=method,mistakes=mistakes,examples=examples))

lesson('power','power_integrals','Power integration, definite integrals and improper endpoints',
 'Reverse the power and chain rules, evaluate with the correct limits and test an unbounded endpoint using a limit.',
 'Find complete power antiderivatives, evaluate signed definite integrals and recognise simple convergent or divergent improper integrals.',
 '<p>Recall rational indices, expanding brackets, derivatives of powers and the chain rule.</p>',
 r'''<h3>Integration reverses differentiation</h3>\[\int x^n\,dx=\frac{x^{n+1}}{n+1}+C,\qquad n\ne-1.\]<p>Increase the power before dividing. Rewrite roots and reciprocals with rational indices and integrate each term. Expand a product when that makes the powers easier to read. The constant is needed because differentiating it gives zero.</p>
 <h3>A linear inner expression brings a divisor</h3>\[\int (ax+b)^n\,dx=\frac{(ax+b)^{n+1}}{a(n+1)}+C,\quad a\ne0,\ n\ne-1.\]<p>Differentiate the proposed answer to check both factors. If the original integrand has an excluded input, integration does not restore it. The power rule does not cover \(x^{-1}\); logarithmic integration belongs to a later course.</p>
 <h3>A definite integral is signed</h3>\[\int_a^b f(x)\,dx=F(b)-F(a).\]<p>Use upper minus lower, including brackets around a negative lower value. An arbitrary constant cancels. Reversing the limits changes the sign; a negative answer can be a correct signed integral.</p>
 <h3>An undefined endpoint needs a one-sided limit</h3>\[\int_0^b x^{-\frac12}\,dx=\lim_{\varepsilon\to0^+}\bigl[2\sqrt{x}\bigr]_{\varepsilon}^{b}.\]<p>Do not substitute into an undefined integrand. Test the antiderivative difference as the boundary is approached from inside the domain. A finite limit gives a convergent improper integral; an infinite limit is not a finite area. At an infinite endpoint, take the corresponding limit instead of treating infinity as an ordinary number.</p>''',
 '<ol><li>Rewrite the integrand and retain its domain.</li><li>Integrate and check the result by differentiation.</li><li>For an indefinite integral include a constant or use the supplied condition.</li><li>For a definite integral use upper minus lower; use a limit at an improper endpoint.</li></ol>',
 ['Increase the index before dividing.', 'Retain the reciprocal inner multiplier.', 'A definite integral is not automatically a geometric area.', 'An unbounded integrand can have a finite improper integral.'],[
 ex('Roots and reciprocal powers in one integral',r'<p>Find \(\int(6\sqrt{x}-4x^{-2}+3)\,dx\) on \(x>0\).</p>',r'\[\int(6x^{\frac12}-4x^{-2}+3)\,dx=4x^{\frac32}+\frac4x+3x+C.\]<p>Differentiating gives the original integrand. In particular, the derivative of \(\frac4x\) is negative. The original domain remains \(x>0\).</p>','IN-POWERS'),
 ex('Divide by both the new power and the inner gradient',r'<p>Find \(\int(3x-2)^4\,dx\).</p>',r'\[\int(3x-2)^4\,dx=\frac{(3x-2)^5}{15}+C.\]<p>The derivative multiplies by both 5 and 3; the denominator 15 reverses both factors.</p>','IN-LINEAR-POWER'),
 ex('Keep the order of the limits',r'<p>Evaluate \(\int_1^{-1}(x^2-1)\,dx\).</p>',r'\[\left[\frac{x^3}{3}-x\right]_1^{-1}=\frac23-\left(-\frac23\right)=\frac43.\]<p>The integrand is non-positive between the endpoints, but the limits are reversed. With limits from \(-1\) to 1 the signed answer is \(-\frac43\).</p>','IN-REVERSED-LIMITS'),
 ex('An infinite height need not give an infinite integral',r'<p>Evaluate \(\int_0^4 x^{-\frac12}\,dx\) and decide whether \(\int_0^4 x^{-\frac32}\,dx\) is finite.</p>',r'\[\lim_{\varepsilon\to0^+}\left(4-2\sqrt{\varepsilon}\right)=4.\]<p>The first integral converges. For the second,</p>\[\left[-2x^{-\frac12}\right]_{\varepsilon}^4=-1+\frac2{\sqrt{\varepsilon}}\longrightarrow+\infty.\]<p>Thus the second integral diverges; there is no finite value to report. At an infinite upper boundary a separate limit is needed: \(\int_2^\infty x^{-2}\,dx=\lim_{b\to\infty}[-x^{-1}]_2^b=\frac12\).</p>','IN-IMPROPER')])

lesson('curves','curve_equations','Recovering a curve from its gradient',
 'A gradient determines a family. Use a point, tangent or stationary level to select the complete curve.',
 'Recover a curve with its constant, use geometric information correctly and retain the original gradient domain.',
 '<p>Recall curve points, tangent and normal gradients, stationary points and exact substitution.</p>',
 r'''<h3>A derivative alone leaves a family</h3><p>If \(f^{\prime}(x)=2x\), every \(f(x)=x^2+C\) has that derivative. A point fixes the vertical constant.</p>'''+image('family-of-curves','Vertical translations share the same derivative')+r'''
 <h3>Use the given point after integration</h3><p>First find an antiderivative with its constant, then substitute both coordinates of the point. Check the final equation against both the derivative and the point.</p>'''+image('initial-condition','A specified point selects one curve from an antiderivative family')+r'''
 <h3>Position and direction give different equations</h3><p>A curve point constrains \(f\); a tangent direction constrains \(f^{\prime}\). A finite nonzero normal gradient gives the tangent gradient by a negative reciprocal. A stationary input gives \(f^{\prime}(a)=0\), while a stationary level gives \(f(a)\). Use the correct condition for each unknown.</p>
 <h3>The original domain remains part of the answer</h3><p>A recovered expression may have a finite endpoint value even where the supplied gradient was undefined. Unless an extension is specified, keep the original interval. If you rewrite the final curve with \(u=\sqrt{x}\), differentiate and integrate with respect to x first; u is only a convenient answer representation.</p>''',
 '<ol><li>Integrate the complete gradient and include its constant.</li><li>Use direction or stationary information to determine any gradient parameters.</li><li>Substitute the actual curve point or level to find the constant.</li><li>Restore every requested coordinate, line and domain; check both original conditions.</li></ol>',
 ['A slope is not a y-coordinate.', 'Do not discard the constant when a complete curve is requested.', 'A normal gradient is not the tangent gradient.', 'A simplified antiderivative does not change the original domain.'],[
 ex('A point selects the constant',r'<p>A curve has \(f^{\prime}(x)=6x-4\) and passes through \((2,5)\). Find its equation.</p>',r'\[f(x)=3x^2-4x+C.\]<p>At the point, \(5=12-8+C\), so \(C=1\).</p>\[y=3x^2-4x+1.\]<p>This expression gives both the stated gradient and the given point.</p>','IN-CURVE-POINT'),
 ex('A fractional-power gradient with an original restriction',r'<p>A curve has \(f^{\prime}(x)=3\sqrt{x}-\frac2{\sqrt{x}}\) for \(x>0\), and \(f(4)=1\). Find f.</p>',r'\[f(x)=2x^{\frac32}-4\sqrt{x}+C.\]<p>At \(x=4\), \(1=16-8+C\), so</p>\[f(x)=2x^{\frac32}-4\sqrt{x}-7,\quad x>0.\]<p>The original gradient was supplied only for positive x. In terms of \(u=\sqrt{x}\), the same final curve is \(2u^3-4u-7\).</p>','IN-CURVE-ROOT'),
 ex('A normal direction and a point fix different constants',r'<p>A curve has \(f^{\prime}(x)=kx-2\). At \((2,3)\) its normal gradient is \(-\frac16\). Find k, the curve and the tangent.</p>',r'<p>The tangent gradient is 6, so \(2k-2=6\) and \(k=4\). Integration gives \(f(x)=2x^2-2x+C\). The point gives \(3=8-4+C\), hence \(C=-1\).</p>\[y=2x^2-2x-1,\qquad y=6x-9\text{ (tangent).}\]','IN-CURVE-NORMAL'),
 ex('A stationary level determines the vertical position',r'<p>A curve has \(f^{\prime}(x)=3x^2-3\) and a local maximum of height 5. Find its equation and both stationary points.</p>',r'\[f(x)=x^3-3x+C,\qquad f^{\prime\prime}(x)=6x.\]<p>The maximum occurs at \(x=-1\); its height is \(2+C=5\), so \(C=3\). The curve is</p>\[y=x^3-3x+3.\]<p>Its stationary points are \((-1,5)\), a maximum, and \((1,1)\), a minimum.</p>','IN-STATIONARY-LEVEL')])

lesson('areas','areas','Signed integrals and geometric areas',
 'Sketch or compare the boundaries, find every change of order and add positive pieces of geometric area.',
 'Distinguish signed accumulation from area, use correct intersections and determine an unknown boundary from an area condition.',
 '<p>Recall roots, intersections, curve signs and definite integration.</p>',
 r'''<h3>An integral can cancel positive and negative pieces</h3><p>\(\int_a^b f(x)\,dx\) is signed. Geometric area is non-negative. Split at every x-axis crossing where the sign changes, then add the magnitudes of the pieces.</p>'''+image('signed-area','Signed integral and total geometric area differ when the curve changes sign')+r'''
 <h3>Between two curves use upper minus lower</h3>\[A=\int_a^b\bigl(f(x)-g(x)\bigr)\,dx\quad\text{if }f(x)\ge g(x).\]<p>Find intersections from the original equations. Check which curve is above on each interval; split again if their order changes. An endpoint can also be a supplied vertical boundary rather than an intersection.</p>'''+image('between-curves','A line lies above a parabola between their intersection points')+r'''
 <h3>Keep the diagram and limits consistent</h3><p>A sketch identifies the relevant bounded region; it does not replace the intersection calculation. For a horizontal strip use right minus left with respect to y, and convert the limits to y-values.</p>
 <h3>An area condition can determine a boundary</h3><p>Integrate with the unknown endpoint still present. Solve the resulting equation, then filter by the original boundary direction and domain. A second algebraic root may describe the wrong region.</p>''',
 '<ol><li>Find the actual boundaries and all relevant intersections.</li><li>Determine the signs or upper/lower order on each subinterval.</li><li>Integrate the positive difference for each geometric piece.</li><li>Add all pieces and restore restrictions on any unknown endpoint.</li></ol>',
 ['The absolute value of one total integral can still miss area.', 'Use every change of sign or curve order.', 'Find intersections before choosing the limits.', 'A negative boundary root can be inadmissible even when its algebra is correct.'],[
 ex('Cancellation hides geometric area',r'<p>For \(y=x^2-1\) on \([-2,2]\), find the signed integral and the total area between the curve and the x-axis.</p>',r'<p>The roots are \(-1\) and 1. The three signed pieces, in order, are \(\frac43,-\frac43,\frac43\). Thus</p>\[\int_{-2}^2(x^2-1)\,dx=\frac43,\]\[A=\frac43+\frac43+\frac43=4.\]<p>Taking the absolute value only after combining the pieces would give the wrong area.</p>','IN-SIGNED-AREA'),
 ex('Intersections choose the limits',r'<p>Find the area enclosed by \(y=2x\) and \(y=x^2\).</p>',r'\[x^2=2x\quad\Rightarrow\quad x=0,2.\]<p>The line is above the parabola between these inputs, so</p>\[A=\int_0^2(2x-x^2)\,dx=\left[x^2-\frac{x^3}{3}\right]_0^2=\frac43.\]','IN-BETWEEN-CURVES'),
 ex('Two lobes have zero signed sum',r'<p>Find the signed integral and total area for \(y=x^3-x\) between \(x=-1\) and \(x=1\).</p>',r'<p>The roots are \(-1,0,1\). The curve is positive on \((-1,0)\) and negative on \((0,1)\). The primitive is \(\frac{x^4}{4}-\frac{x^2}{2}\).</p>\[I=0,\qquad A=\frac14+\frac14=\frac12.\]<p>Zero signed change does not mean that no region is enclosed.</p>','IN-TWO-LOBES'),
 ex('The required side of the axis selects the root',r'<p>The region under \(y=2x+1\) from \(x=0\) to \(x=b\), where \(b>0\), has area 6. Find b.</p>',r'\[b^2+b=6\quad\Rightarrow\quad (b-2)(b+3)=0.\]<p>The condition \(b>0\) retains only \(b=2\). The root \(-3\) does not describe the specified region to the right of the origin.</p>','IN-MISSING-BOUNDARY')])

lesson('volumes','volumes','Volumes of revolution about either coordinate axis',
 'Use distance from the axis as the radius and sum circular cross-sections in the matching variable.',
 'Build disk and washer integrals about either axis, including the hole and the correct transformed boundaries.',
 '<p>Recall area of a circle, curve intersections, rearranging equations and definite integrals.</p>',
 r'''<h3>Cross-sectional area gives volume</h3><p>Rotating a region touching the x-axis gives disks perpendicular to that axis:</p>\[V=\pi\int_a^b y^2\,dx.\]<p>The radius is a distance from the axis. Square the radius, then integrate with respect to the strip direction.</p>'''+image('disk-volume','A thin strip becomes a circular cross-section on rotation')+r'''
 <h3>A region away from the axis leaves a hole</h3>\[V=\pi\int_a^b\bigl(R(x)^2-r(x)^2\bigr)\,dx.\]<p>Use the larger distance for the outer radius and the smaller distance for the inner radius. Subtract the squares; \((R-r)^2\) is the area of a different circle. Check any sign changes relative to the axis before using a washer formula.</p>
 <h3>About the y-axis use horizontal cross-sections</h3>\[V=\pi\int_c^d\bigl(R(y)^2-r(y)^2\bigr)\,dy.\]<p>Express x as a function of y and convert the boundaries to y-values. A polynomial in y must be integrated with respect to y. Do not interchange dx and dy while keeping the same integrand and limits.</p>
 <h3>One region gives different solids about different axes</h3><p>The axis determines radii and limits. Identify the actual region first; do not rotate the whole area under each curve separately if that would fill an intended hole. Include π and cubic units in the final volume.</p>''',
 '<ol><li>Identify the region and the axis of revolution.</li><li>Choose cross-sections perpendicular to that axis.</li><li>Write outer and inner radii as distances, using the matching variable and limits.</li><li>Integrate π times the difference of their squares and check positivity and units.</li></ol>',
 ['Square radii before subtracting.', 'Do not omit an inner hole.', 'About the y-axis convert both the expression and limits.', 'A final volume needs π and cubic units when lengths have units.'],[
 ex('A sloping profile gives disks',r'<p>Rotate the region under \(y=1+x\), above the x-axis, from \(x=0\) to 2 about the x-axis. Find its volume.</p>',r'\[V=\pi\int_0^2(1+x)^2\,dx=\pi\left[x+x^2+\frac{x^3}{3}\right]_0^2=\frac{26\pi}{3}.\]<p>The integrand is the square of the entire radius, including its cross term.</p>','IN-DISKS'),
 ex('An inner boundary removes a cone-shaped hole',r'<p>The region \(0\le x\le2\), \(x\le y\le2\) is rotated about the x-axis. Find the volume.</p>',r'<p>The outer radius is 2 and the inner radius is x, so</p>\[V=\pi\int_0^2(4-x^2)\,dx=\frac{16\pi}{3}.\]<p>Using \((2-x)^2\) would square the thickness instead of subtracting circular areas.</p>','IN-WASHERS'),
 ex('A vertical axis changes the integration variable',r'<p>Rotate the region between \(x=0\) and \(x=y^2\), for \(0\le y\le2\), about the y-axis.</p>',r'<p>A horizontal strip gives radius \(y^2\). Therefore</p>\[V=\pi\int_0^2 y^4\,dy=\frac{32\pi}{5}.\]<p>The limits are y-values, not x-values. The radius must be squared even though x is already a square.</p>','IN-Y-AXIS'),
 ex('The same region, two different axes',r'<p>The curves \(y=x\) and \(y=x^2\) enclose a region in the first quadrant. Find its volumes about the x-axis and about the y-axis.</p>',r'<p>The intersections are \((0,0)\) and \((1,1)\). For x-axis rotation,</p>\[V_x=\pi\int_0^1(x^2-x^4)\,dx=\frac{2\pi}{15}.\]<p>For y-axis rotation, the outer radius is \(\sqrt{y}\), the inner radius is y:</p>\[V_y=\pi\int_0^1(y-y^2)\,dy=\frac{\pi}{6}.\]<p>Both setups use washers, but their radii and integration variables differ.</p>','IN-TWO-AXES')])

lesson('conditions','accumulation','Constants, parameters and repeated integration',
 'Separate the constants from successive integrations and combine shape, position and accumulation conditions.',
 'Recover a curve from a second derivative, determine parameters, recognise a useful derivative and interpret net accumulation.',
 '<p>Recall first and second derivatives, initial conditions, signed integrals and stationary-point classification.</p>',
 r'''<h3>Two integrations produce two independent constants</h3>\[f^{\prime\prime}(x)\ \longrightarrow\ f^{\prime}(x)+\text{first constant}\ \longrightarrow\ f(x)+\text{second constant}.\]<p>Use a gradient condition for the first derivative and a point condition for the function. A stationary condition supplies a zero gradient. Do not reuse one constant as if both conditions described the same quantity.</p>
 <h3>A coefficient and an integration constant are different unknowns</h3><p>Use the supplied gradient, point, area or stationary information in the appropriate original expression. Solve the complete system and check it before drawing conclusions about the curve.</p>
 <h3>A known derivative can identify an integral</h3><p>Differentiate a proposed product using expansion or the chain rule. If its derivative is a constant multiple of the required integrand, reverse that relation. This is a recognition method, not a requirement to introduce integration by parts or a new nonlinear substitution technique.</p>
 <h3>Integrating a rate gives signed change</h3>\[A(t)=A(0)+\int_0^t q(v)\,dv.\]<p>When the rate changes sign, the accumulated amount may start falling even though earlier accumulation was positive. A maximum amount is found from the sign of the rate and comparison with the interval endpoints.</p>'''+image('accumulation','A positive rate followed by a negative rate gives a maximum amount before the final time'),
 '<ol><li>Identify which expression each condition constrains.</li><li>Keep a separate constant for each integration.</li><li>Solve and restore the original derivative and value conditions.</li><li>For a mixed problem check signs, boundaries, units and the meaning of the requested quantity.</li></ol>',
 ['A condition on f′ does not directly determine f.', 'Two integrations need two independently determined constants.', 'A negative later rate reduces an earlier accumulated amount.', 'Recognising a derivative still requires checking its full multiplier.'],[
 ex('A gradient condition and a point condition',r'<p>Given \(f^{\prime\prime}(x)=12x-6\), \(f^{\prime}(1)=3\) and \(f(0)=2\), find f.</p>',r'\[f^{\prime}(x)=6x^2-6x+C_1.\]<p>The gradient condition gives \(C_1=3\). Integrate again:</p>\[f(x)=2x^3-3x^2+3x+C_2.\]<p>The point gives \(C_2=2\). Each constant belongs to a different integration.</p>','IN-TWO-CONSTANTS'),
 ex('Recover a gradient coefficient before the vertical constant',r'<p>A curve has \(f^{\prime}(x)=ax^2-2\), \(f^{\prime}(1)=4\) and \(f(1)=1\). Find a and f.</p>',r'<p>The first condition gives \(a-2=4\), so \(a=6\). Then</p>\[f(x)=2x^3-2x+C.\]<p>The point gives \(1=2-2+C\), hence \(f(x)=2x^3-2x+1\).</p>','IN-COEFFICIENT'),
 ex('A final amount can be below its earlier maximum',r'<p>A model has \(A(0)=10\) and \(A^{\prime}(t)=4-t\) for \(0\le t\le6\). Find A, the final amount and the greatest amount.</p>',r'\[A(t)=10+4t-\frac{t^2}{2}.\]<p>The rate changes from positive to negative at \(t=4\), so the greatest amount is \(A(4)=18\). The final amount is \(A(6)=16\). The last interval removes 2 from the previously reached maximum.</p>','IN-ACCUMULATION'),
 ex('Use a derivative to evaluate a less obvious integral',r'<p>Differentiate \(F(x)=x^2(x+1)^3\). Hence evaluate \(\int_0^1 x(x+1)^2(5x+2)\,dx\).</p>',r'<p>Expanding before differentiating, or differentiating the product, gives</p>\[F^{\prime}(x)=x(x+1)^2(5x+2).\]<p>The required integrand is precisely this derivative, so</p>\[I=F(1)-F(0)=8.\]<p>There is no need to invent a separate integration rule for the product.</p>','IN-RECOGNITION')])

def field(key,label,kind,expected,**extra):return dict(key=key,label=label,type=kind,expected=str(expected),**extra)
def pairs(*ps):return ';'.join('('+','.join(str(s.simplify(v)) for v in a)+')' for a in ps)
def values(*vs):return '{'+','.join(str(s.simplify(v)) for v in vs)+'}'
def show(f):
 v=f['expected']
 if f['type']=='choice':return f['options'][v]
 if f['type']=='pairs':return r'\(\{'+r',\ '.join('('+r',\ '.join(tex(z) for z in a[1:-1].split(','))+')' for a in v.split(';'))+r'\}\)'
 if f['type']=='set':
  if v.startswith('{'):return r'\(\{'+r',\ '.join(tex(a) for a in v[1:-1].split(','))+r'\}\)'
  return r'\('+v.replace('inf',r'\infty').replace(' U ',r'\cup ')+r'\)'
 return math(v)
def quick(topic,family,v,title,prompt,fields,solution,model):
 uid=f'M4U-9709-P1-IN-CHECK-{topic.upper()}-{family}-{v}'
 answer=''.join('<p>'+f['label']+': '+show(f)+'</p>' for f in fields)
 hints={'power':'Rewrite powers, reverse the derivative and retain the limits or supplied normalising condition.',
 'curves':'Integrate first; then use each original direction, point and domain condition in the appropriate expression.',
 'areas':'Find every sign or order change and add positive pieces of geometric area.',
 'volumes':'Use distances from the specified axis, subtract squared radii and match the variable to the limits.',
 'conditions':'Keep successive constants separate and restore all original gradient, value and boundary conditions.'}
 questions.append(dict(id=uid,family_uid=f'M4U-9709-P1-IN-CHECK-{topic.upper()}-{family}',lesson=topic,title=title,collection='short' if v==0 else 'variant',prompt_html=prompt,answer_html=answer,solution_html=solution+'<h4>Complete answers</h4>'+answer,hint_html='<p>'+hints[topic]+'</p>',marks=len(fields),difficulty=2,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='B1',marks=1,description_html='Complete correct answer for '+f['label']+'.') for f in fields])],verification=uid))
 models.append(dict(uid=uid,**model))

for v in range(2):
 G=6*x*x-4*x+3 if v==0 else 12*x**3+6*x-2;F=s.integrate(G,x)
 quick('power',1,v,'A complete antiderivative with a specified constant',r'<p>Find \(F(x)\) such that \(F^{\prime}(x)='+tex(G)+r'\) and \(F(0)=0\). Then select why the unrestricted indefinite integral also needs a constant.</p>',
  [field('primitive','Complete function F(x)','polynomial',F,variables=['x']),field('constant','Why include C without the condition?','choice','B' if v==0 else 'C',options={'A':'A derivative determines one vertical position','B':'Every constant has zero derivative','C':'A constant is needed only for negative powers'} if v==0 else {'A':'A constant is needed only for definite integrals','B':'An integrand determines one curve point','C':'Every constant has zero derivative'})],r'<p>Integrate every term, then use \(F(0)=0\). Without that value condition, adding a constant leaves the derivative unchanged.</p>',dict(kind='primitive',G=str(G),at=0,value=0))
 a,b,n=(2,1,3) if v==0 else (3,-2,2);G=(a*x+b)**n;F=(a*x+b)**(n+1)/s.Integer(a*(n+1));lo,hi=(0,1) if v==0 else (1,2);value=F.subs(x,hi)-F.subs(x,lo)
 quick('power',2,v,'A whole linear-power primitive',r'<p>Given \(F^{\prime}(x)='+tex(G)+r'\) and \(F('+tex(-s.Rational(b,a))+r')=0\), give the complete F. Also evaluate \(\int_{'+str(lo)+'}^{'+str(hi)+'}'+tex(G)+r'\,dx\).</p>',
  [field('primitive','Complete function F(x)','polynomial',s.expand(F),variables=['x']),field('integral','Definite integral','number',value)],r'<p>Divide by both the new power and the inner gradient. The normalising input makes the inner expression zero. For the definite integral use upper minus lower.</p>',dict(kind='linear_power',a=a,b=b,n=n,lo=lo,hi=hi))
 a=1+v;G=x*x-a*a;F=s.integrate(G,x);value=F.subs(x,a)-F.subs(x,-a)
 quick('power',3,v,'A signed integral and its reversal',r'<p>For \(f(x)='+tex(G)+r'\), evaluate \(\int_{-'+str(a)+'}^{'+str(a)+r'} f(x)\,dx\) and \(\int_{'+str(a)+'}^{-'+str(a)+r'} f(x)\,dx\).</p>',
  [field('forward','Integral with increasing limits','number',value),field('reversed','Integral with reversed limits','number',-value)],r'<p>The integrand is non-positive on the interval. Reversing the limits negates the signed result; it does not change the integrand.</p>',dict(kind='reversed',a=a))
 G=x**s.Rational(-1,2) if v==0 else x**-2;F=2*s.sqrt(x) if v==0 else -1/x;lo,hi=(0,s.Integer(4)) if v==0 else (s.Integer(2),s.oo);value=s.Integer(4) if v==0 else s.Rational(1,2);choice='A' if v==0 else 'C'
 quick('power',4,v,'An improper endpoint with a finite limit',r'<p>Evaluate \(\int_{'+tex(lo)+'}^{'+tex(hi)+'}'+tex(G)+r'\,dx\) using a limit. Use the power-rule primitive with no added constant. Give its limit at the improper boundary and decide whether the integral converges.</p>',
  [field('boundary','Limit of the selected primitive at the improper boundary','number',0),field('integral','Value of the improper integral','number',value),field('convergence','Conclusion','choice',choice,options={'A':'Converges to a finite value','B':'Diverges because the integrand is undefined at zero','C':'It is an ordinary integral of a continuous function at zero'} if v==0 else {'A':'Every infinite interval gives an infinite integral','B':'Infinity can be substituted as an ordinary real number','C':'Converges to a finite value'})],r'<p>Evaluate the primitive on a finite interior interval first. At the improper boundary take the appropriate limit. A finite primitive difference gives the convergent value even when an endpoint is undefined or infinite.</p>',dict(kind='improper',G=str(G),F=str(F),lo=str(lo),hi=str(hi),boundary='lower' if v==0 else 'upper'))


 a,b,X,Y=(3,-4,2,5) if v==0 else (2,3,1,4);G=2*a*x+b;C=Y-a*X*X-b*X;F=a*x*x+b*x+C
